import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"20、【观】 坤下巽上","description":"横渠易说 - 20、【观】 坤下巽上","frontmatter":{"title":"20、【观】 坤下巽上","description":"横渠易说 - 20、【观】 坤下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/022.md","filePath":"zh/classics/hengqu/022.md"}'),l={name:"zh/classics/hengqu/022.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_20、【观】-坤下巽上" tabindex="-1">20、【观】 坤下巽上 <a class="header-anchor" href="#_20、【观】-坤下巽上" aria-label="Permalink to “20、【观】 坤下巽上”">​</a></h1><p>盥求神而荐亵也。</p><h3 id="彖曰-大观在上-顺而巽-中正以观天下。-观盥而不荐-有孚颙若-下观而化也。观天之神道而四时不忒-圣人以神道设教而天下服矣。" tabindex="-1">彖曰：大观在上，顺而巽，中正以观天下。“观盥而不荐，有孚颙若”，下观而化也。观天之神道而四时不忒，圣人以神道设教而天下服矣。 <a class="header-anchor" href="#彖曰-大观在上-顺而巽-中正以观天下。-观盥而不荐-有孚颙若-下观而化也。观天之神道而四时不忒-圣人以神道设教而天下服矣。" aria-label="Permalink to “彖曰：大观在上，顺而巽，中正以观天下。“观盥而不荐，有孚颙若”，下观而化也。观天之神道而四时不忒，圣人以神道设教而天下服矣。”">​</a></h3><h3 id="象曰-风行地上-观-先王以省方观民设教。" tabindex="-1">象曰：风行地上，观，先王以省方观民设教。 <a class="header-anchor" href="#象曰-风行地上-观-先王以省方观民设教。" aria-label="Permalink to “象曰：风行地上，观，先王以省方观民设教。”">​</a></h3><p>内顺外巽，示民以顺而外从巽，此祭所以为教之本，故盥而不荐。“中正以观天下”，又曰“大观在上”，皆谓五也，凡言“观我生”，亦皆谓五也。天不言，藏其用而四时行。神道，如“盥而不荐”之类，盥简洁而神，荐亵近而烦也。 有两则须有感，然天之感有何思虑？莫非自然。圣人则能用感，何谓用感？凡教化设施，皆是用感也，作于此化于彼者，皆感之道，圣人以神道设教是也。 天不言而四时行，圣人［神道］设教而天下服，诚于此，动于彼，神之道欤!</p><h3 id="初六-童观-小人无咎-君子吝。-象曰-初六童观-小人道也。" tabindex="-1">初六，童观，小人无咎，君子吝。 象曰：“初六童观”，小人道也。 <a class="header-anchor" href="#初六-童观-小人无咎-君子吝。-象曰-初六童观-小人道也。" aria-label="Permalink to “初六，童观，小人无咎，君子吝。 象曰：“初六童观”，小人道也。”">​</a></h3><p>所观者末，小人之道，施于君子则吝。</p><h3 id="六二-窥观-利女贞。-象曰-窥观女贞-亦可丑也。" tabindex="-1">六二，窥观，利女贞。 象曰：“窥观女贞”，亦可丑也。 <a class="header-anchor" href="#六二-窥观-利女贞。-象曰-窥观女贞-亦可丑也。" aria-label="Permalink to “六二，窥观，利女贞。 象曰：“窥观女贞”，亦可丑也。”">​</a></h3><p>得妇人之道，虽正可羞。</p><h3 id="六三-观我生进退。-象曰-观我生进退-未失道也。" tabindex="-1">六三，观我生进退。 象曰：“观我生进退”，未失道也。 <a class="header-anchor" href="#六三-观我生进退。-象曰-观我生进退-未失道也。" aria-label="Permalink to “六三，观我生进退。 象曰：“观我生进退”，未失道也。”">​</a></h3><p>观上所施而进退，虽以阴居阳，于道未失，以其在下卦之体而应于上，故曰“进退”。</p><h3 id="六四-观国之光-利用宾于王。-象曰-观国之光-尚宾也。" tabindex="-1">六四，观国之光，利用宾于王。 象曰：“观国之光”，尚宾也。 <a class="header-anchor" href="#六四-观国之光-利用宾于王。-象曰-观国之光-尚宾也。" aria-label="Permalink to “六四，观国之光，利用宾于王。 象曰：“观国之光”，尚宾也。”">​</a></h3><p>体柔巽而以阴居下宾之，必无过也，故利。下一作阴。</p><h3 id="九五-观我生-君子无咎。-象曰-观我生-观民也。" tabindex="-1">九五，观我生，君子无咎。 象曰：“观我生”，观民也。 <a class="header-anchor" href="#九五-观我生-君子无咎。-象曰-观我生-观民也。" aria-label="Permalink to “九五，观我生，君子无咎。 象曰：“观我生”，观民也。”">​</a></h3><p>观我所自出者。</p><h3 id="上九-观其生-君子无咎。-象曰-观其生-志未平也。" tabindex="-1">上九，观其生，君子无咎。 象曰：“观其生”，志未平也。 <a class="header-anchor" href="#上九-观其生-君子无咎。-象曰-观其生-志未平也。" aria-label="Permalink to “上九，观其生，君子无咎。 象曰：“观其生”，志未平也。”">​</a></h3><p>以刚阳极上之德，居不臣不任之位，以观国家之政，志有所未平也，有君子循理之心则可免咎。俯视九五之为，故曰“观其生”。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
